using System;
using System.IO;
using System.IO.Compression;
using System.Text;
using System.Collections.Generic;
using System.Diagnostics;
using System.Reflection;
using System.Threading;

namespace UsbBridge {
// Versioned, per-user installs leave the running portable copy and its files intact.
// A bad download never changes the pointer used by the old desktop shortcut.
internal static class UpdateInstaller {
 internal static string Root{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"USBBridge\\updates");}}
 internal static string VersionDirectory(string root,UpdateRelease release){return Path.Combine(root,release.Code.ToString(System.Globalization.CultureInfo.InvariantCulture));}
 internal static string Prepare(string root,UpdateRelease release,string archive){if(new FileInfo(archive).Length!=release.Size||!UpdateManifest.HashFile(archive).Equals(release.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Update checksum mismatch");string target=VersionDirectory(root,release),temp=target+".staging-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(temp);try{SafeUpdateZip.Extract(archive,temp);string exe=Path.Combine(temp,"USBBridge.exe");FileVersionInfo actual=FileVersionInfo.GetVersionInfo(exe);if(actual.FileMajorPart!=new Version(release.Name).Major||actual.FileMinorPart!=new Version(release.Name).Minor||actual.FileBuildPart!=new Version(release.Name).Build)throw new InvalidDataException("Unexpected executable version");File.Copy(archive,Path.Combine(temp,"release.zip"));File.WriteAllBytes(Path.Combine(temp,"release.manifest"),release.Envelope);if(Directory.Exists(target)){ValidateInstalled(target,release);Directory.Delete(temp,true);}else Directory.Move(temp,target);return target;}catch{try{if(Directory.Exists(temp))Directory.Delete(temp,true);}catch{}throw;}}
 internal static void ValidateInstalled(string folder,UpdateRelease release){string archive=Path.Combine(folder,"release.zip");if(new FileInfo(archive).Length!=release.Size||!UpdateManifest.HashFile(archive).Equals(release.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Stored update checksum mismatch");SafeUpdateZip.VerifyInstalled(archive,folder);}
 internal static void Remember(string root,UpdateRelease release){Directory.CreateDirectory(root);string path=Path.Combine(root,"latest.manifest"),temp=path+".new";File.WriteAllBytes(temp,release.Envelope);if(File.Exists(path)){string backup=path+".previous";try{File.Replace(temp,path,backup);return;}catch(PlatformNotSupportedException){}catch(IOException){}File.Delete(temp);throw new IOException("Cannot save the update pointer safely");}File.Move(temp,path);}
 internal static bool TryForward(string[] args){if(args.Length!=0&&args[0]!="--idle"&&args[0]!="--update-launch")return false;try{string pointer=Path.Combine(Root,"latest.manifest");if(!File.Exists(pointer))return false;UpdateRelease release=UpdateManifest.Read(ReadBounded(pointer,196608));if(release==null||release.Code<=UpdateManifest.CurrentCode)return false;string folder=VersionDirectory(Root,release);ValidateInstalled(folder,release);ProcessStartInfo start=new ProcessStartInfo(Path.Combine(folder,"USBBridge.exe"));start.WorkingDirectory=folder;start.UseShellExecute=true;start.Arguments=args.Length==0?"":"--idle";Process.Start(start);return true;}catch(Exception e){DiagnosticLog.Write("Update startup fallback: "+e.Message);return false;}}
 internal static byte[] ReadBounded(string path,int maximum){using(FileStream file=File.OpenRead(path)){if(file.Length>maximum)throw new InvalidDataException("Update metadata too large");byte[] bytes=new byte[(int)file.Length];int at=0;while(at<bytes.Length){int read=file.Read(bytes,at,bytes.Length-at);if(read<=0)throw new EndOfStreamException();at+=read;}return bytes;}}
 internal static void Launch(string folder){ProcessStartInfo start=new ProcessStartInfo(Path.Combine(folder,"USBBridge.exe"));start.WorkingDirectory=folder;start.UseShellExecute=true;start.Arguments="--update-launch "+Process.GetCurrentProcess().Id;Process.Start(start);}
 // Called only by the new process after it owns the desktop mutex and has shown
 // its form. Merely downloading or launching a candidate cannot redirect an old shortcut.
 internal static void ConfirmCurrentInstallation(){try{ConfirmInstallation(Root,Assembly.GetExecutingAssembly().Location,UpdateManifest.CurrentCode,UpdateManifest.CurrentName,UpdateManifest.PublicModulus,UpdateManifest.PublicExponent);}catch(Exception error){DiagnosticLog.Write("Update pointer not committed: "+error.Message);}}
 internal static bool ConfirmInstallation(string root,string executable,int code,string name,string modulus,string exponent){string folder=Path.GetDirectoryName(Path.GetFullPath(executable)),manifest=Path.Combine(folder,"release.manifest");if(!File.Exists(manifest))return false;UpdateRelease release=UpdateManifest.Read(ReadBounded(manifest,196608),modulus,exponent);if(release==null||release.Code!=code||release.Name!=name||!Path.GetFullPath(VersionDirectory(root,release)).Equals(folder,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Update launch identity mismatch");ValidateInstalled(folder,release);Remember(root,release);return true;}
 internal static bool WaitForPrevious(string[] args){if(args.Length!=2||args[0]!="--update-launch")return true;int pid;if(!int.TryParse(args[1],out pid)||pid<=0||pid==Process.GetCurrentProcess().Id)return false;try{using(Process previous=Process.GetProcessById(pid))return previous.WaitForExit(15000);}catch(ArgumentException){return true;}}
}

internal sealed class SafeUpdateZip {
 sealed class Entry {internal string Name;internal uint Packed,Length,Offset,Crc;internal ushort Flags,Method;}
 static ushort U16(byte[] b,int i){return (ushort)(b[i]|b[i+1]<<8);}
 static uint U32(byte[] b,int i){return (uint)(b[i]|b[i+1]<<8|b[i+2]<<16|b[i+3]<<24);}
 static byte[] Read(Stream stream,int count){byte[] b=new byte[count];int at=0;while(at<count){int n=stream.Read(b,at,count-at);if(n<=0)throw new EndOfStreamException();at+=n;}return b;}
 static List<Entry> Entries(FileStream file){if(file.Length<22||file.Length>UpdateManifest.MaxAssetBytes)throw new InvalidDataException("ZIP size");int tailSize=(int)Math.Min(file.Length,65557);file.Position=file.Length-tailSize;byte[] tail=Read(file,tailSize);int end=-1;for(int i=tail.Length-22;i>=0;i--)if(U32(tail,i)==0x06054b50&&i+22+U16(tail,i+20)==tail.Length){end=i;break;}if(end<0||U16(tail,end+4)!=0||U16(tail,end+6)!=0||U16(tail,end+8)!=U16(tail,end+10))throw new InvalidDataException("ZIP directory");int count=U16(tail,end+10);uint directorySize=U32(tail,end+12),offset=U32(tail,end+16);long directoryEnd=(long)offset+directorySize;if(count<2||count>128||directoryEnd>file.Length-tailSize+end)throw new InvalidDataException("ZIP directory bounds");file.Position=offset;long total=0;List<Entry> entries=new List<Entry>();Dictionary<string,bool> names=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);bool exe=false,config=false;for(int i=0;i<count;i++){byte[] h=Read(file,46);if(U32(h,0)!=0x02014b50||U16(h,34)!=0)throw new InvalidDataException("ZIP entry");ushort flags=U16(h,8),method=U16(h,10);uint packed=U32(h,20),length=U32(h,24),local=U32(h,42);int nameLength=U16(h,28),extraLength=U16(h,30),commentLength=U16(h,32);if((flags&~0x0808)!=0||(method!=0&&method!=8)||packed==uint.MaxValue||length==uint.MaxValue||length>67108864||local>=offset||nameLength<1||nameLength>256)throw new InvalidDataException("Unsupported ZIP entry");string name=new UTF8Encoding(false,true).GetString(Read(file,nameLength));file.Position+=extraLength+commentLength;if(file.Position>directoryEnd)throw new InvalidDataException("ZIP entry bounds");if(name.EndsWith("/",StringComparison.Ordinal)){ValidateName(name.Substring(0,name.Length-1));if(length!=0)throw new InvalidDataException("ZIP directory content");continue;}ValidateName(name);if(names.ContainsKey(name)||name=="release.zip"||name=="release.manifest")throw new InvalidDataException("Duplicate or reserved ZIP file");names[name]=true;if(((U32(h,38)>>16)&0xf000)==0xa000)throw new InvalidDataException("ZIP symlink");total+=length;if(total>268435456)throw new InvalidDataException("ZIP expanded size");Entry entry=new Entry{Name=name,Packed=packed,Length=length,Offset=local,Flags=flags,Method=method,Crc=U32(h,16)};entries.Add(entry);if(name=="USBBridge.exe")exe=true;if(name=="USBBridge.exe.config")config=true;}if(!exe||!config||file.Position!=directoryEnd)throw new InvalidDataException("Incomplete Windows update");return entries;}
 internal static void ValidateName(string name){if(string.IsNullOrEmpty(name)||name.StartsWith("/",StringComparison.Ordinal)||name.IndexOf('\\')>=0||name.IndexOf(':')>=0||name.IndexOf('\0')>=0)throw new InvalidDataException("Unsafe ZIP path");string[] parts=name.Split('/');foreach(string part in parts){if(part.Length==0||part=="."||part==".."||part.EndsWith(".",StringComparison.Ordinal)||part.EndsWith(" ",StringComparison.Ordinal)||part.IndexOfAny(new char[]{'<','>','"','|','?','*'})>=0)throw new InvalidDataException("Unsafe ZIP path");string stem=part.Split('.')[0].ToUpperInvariant();if(stem=="CON"||stem=="PRN"||stem=="AUX"||stem=="NUL"||System.Text.RegularExpressions.Regex.IsMatch(stem,@"^(COM|LPT)[0-9]$"))throw new InvalidDataException("Reserved ZIP path");}}
 static byte[] Content(FileStream file,Entry entry){file.Position=entry.Offset;byte[] header=Read(file,30);if(U32(header,0)!=0x04034b50||U16(header,6)!=entry.Flags||U16(header,8)!=entry.Method)throw new InvalidDataException("ZIP local header");int nameLength=U16(header,26),extraLength=U16(header,28);string localName=new UTF8Encoding(false,true).GetString(Read(file,nameLength));if(localName!=entry.Name)throw new InvalidDataException("ZIP local name mismatch");file.Position+=extraLength;if(file.Position+entry.Packed>file.Length)throw new InvalidDataException("ZIP content bounds");byte[] compressed=Read(file,(int)entry.Packed),content;if(entry.Method==0)content=compressed;else{using(MemoryStream source=new MemoryStream(compressed))using(DeflateStream deflate=new DeflateStream(source,CompressionMode.Decompress))using(MemoryStream expanded=new MemoryStream((int)entry.Length)){byte[] block=new byte[32768];int read;while((read=deflate.Read(block,0,block.Length))>0){if(expanded.Length+read>entry.Length)throw new InvalidDataException("ZIP length overflow");expanded.Write(block,0,read);}content=expanded.ToArray();}}if(content.LongLength!=entry.Length||Crc32(content)!=entry.Crc)throw new InvalidDataException("ZIP checksum mismatch");return content;}
 static uint Crc32(byte[] bytes){uint crc=0xffffffff;foreach(byte value in bytes){crc^=value;for(int i=0;i<8;i++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}return ~crc;}
 internal static void Extract(string archive,string root){Process(archive,root,false);}
 internal static void VerifyInstalled(string archive,string root){Process(archive,root,true);}
 static void Process(string archive,string root,bool verify){string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;using(FileStream file=File.OpenRead(archive)){List<Entry> entries=Entries(file);foreach(Entry entry in entries){string path=Path.GetFullPath(Path.Combine(root,entry.Name.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("ZIP target escaped");byte[] content=Content(file,entry);if(verify){if(!File.Exists(path)||new FileInfo(path).Length!=content.Length||UpdateManifest.HashFile(path)!=UpdateManifest.Hash(content))throw new InvalidDataException("Installed update modified");}else{Directory.CreateDirectory(Path.GetDirectoryName(path));using(FileStream target=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))target.Write(content,0,content.Length);}}}}
}
}
